int linear_search(int a[], int n, int x) {
    for (int i = 0; i < n; i++) {
        if (a[i] == x) {
            return i;
        }
    }
    return -1;
}

int linear_search(int a[], int n, int x) {
    int i = 0;
    while (i < n) {
        if (a[i] == x) {
            return i;
        }
        i++;
    }
    return -1;
}

int linear_search(int a[], int n, int x) {
    int i;
    for (i = n - 1; i >= 0; i--) {
        if (a[i] == x) {
            return i;
        }
    }
    return -1;
}
